/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally
const { fontFamily: interFamily } = loadInter();



export type GrowthChartProps = Record<string, any>;

const GrowthChart: React.FC<GrowthChartProps> = ({
  backgroundColor = "#080808",
  transparentBackground = false,
  durationInSeconds = 4,
  lineColor = "#f23a3a",
  gridColor = "#222222",
  textColor = "#ffffff",
  title = "Quarterly Growth",
  subtitle = "Malloy Studio Performance",
  growthText = "+142%",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Timings
  const totalFrames = durationInSeconds * fps;
  const startDelay = Math.min(20, Math.floor(totalFrames * 0.15));
  const chartStartFrame = startDelay;
  const chartEndFrame = Math.floor(totalFrames * 0.85);

  const titleOpacity = interpolate(frame, [0, startDelay || 1], [0, 1], {
    extrapolateRight: "clamp",
  });

  const growthBadgeScale = spring({
    fps,
    frame: frame - Math.floor(startDelay * 0.5),
    config: { damping: 12 },
  });

  const chartProgress = interpolate(
    frame,
    [chartStartFrame, chartEndFrame],
    [0, 1],
    {
      easing: Easing.inOut(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Data Points defined relative to canvas size
  const DATA_POINTS = [
    { x: 0.1, y: 0.8 },
    { x: 0.18, y: 0.72 },
    { x: 0.27, y: 0.76 },
    { x: 0.38, y: 0.55 },
    { x: 0.48, y: 0.62 },
    { x: 0.6, y: 0.4 },
    { x: 0.72, y: 0.45 },
    { x: 0.83, y: 0.25 },
    { x: 0.9, y: 0.2 },
  ];

  const absPoints = DATA_POINTS.map((p) => ({
    x: p.x * width,
    y: p.y * height,
  }));

  const minX = absPoints[0].x;
  const maxX = absPoints[absPoints.length - 1].x;

  // X coordinate bounds for the revealing clip path
  const currentX = interpolate(chartProgress, [0, 1], [minX, maxX]);

  // Helper to find exact Y position on the piecewise linear graph for a given X
  function getYAtX(x: number, pts: { x: number; y: number }[]) {
    if (x <= pts[0].x) return pts[0].y;
    if (x >= pts[pts.length - 1].x) return pts[pts.length - 1].y;
    for (let i = 0; i < pts.length - 1; i++) {
      if (x >= pts[i].x && x <= pts[i + 1].x) {
        const p1 = pts[i];
        const p2 = pts[i + 1];
        if (p2.x === p1.x) return p1.y; // safety against division by zero
        const t = (x - p1.x) / (p2.x - p1.x);
        return p1.y + t * (p2.y - p1.y);
      }
    }
    return pts[pts.length - 1].y;
  }

  const currentY = getYAtX(currentX, absPoints);

  const linePath = absPoints
    .map((p, i) => `${i === 0 ? "M" : "L"} ${p.x} ${p.y}`)
    .join(" ");
  
  const areaPath = `${linePath} L ${maxX} ${height * 0.9} L ${minX} ${height * 0.9} Z`;

  const yLabels = [
    { y: 0.2, label: "100k" },
    { y: 0.4, label: "75k" },
    { y: 0.6, label: "50k" },
    { y: 0.8, label: "25k" },
  ];

  const leadingDotScale = interpolate(chartProgress, [0, 0.05], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const lineOpacity = interpolate(chartProgress, [0, 0.02], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      
      {/* Background Grid & Labels */}
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", top: 0, left: 0 }}
      >
        {yLabels.map((lbl, i) => {
          const yPos = lbl.y * height;
          return (
            <line
              key={`grid-${i}`}
              x1={width * 0.1}
              y1={yPos}
              x2={width * 0.9}
              y2={yPos}
              stroke={gridColor}
              strokeWidth={2}
              opacity={0.8}
            />
          );
        })}
      </svg>

      <div style={{ position: "absolute", top: 0, left: 0, width, height }}>
        {yLabels.map((lbl, i) => {
          const yPos = lbl.y * height;
          return (
            <div
              key={`label-${i}`}
              style={{
                position: "absolute",
                top: yPos - 15,
                right: width - width * 0.08,
                color: textColor,
                fontSize: 24,
                opacity: titleOpacity * 0.6,
                textAlign: "right",
              }}
            >
              {lbl.label}
            </div>
          );
        })}
      </div>

      {/* Main Chart SVG */}
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", top: 0, left: 0, opacity: lineOpacity }}
      >
        <defs>
          <clipPath id="graph-clip">
            <rect x={0} y={0} width={currentX} height={height} />
          </clipPath>
          <linearGradient id="area-gradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={lineColor} stopOpacity={0.6} />
            <stop offset="100%" stopColor={lineColor} stopOpacity={0.0} />
          </linearGradient>
          <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="8" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>

        {/* Gradient Area Fill */}
        <path
          d={areaPath}
          fill="url(#area-gradient)"
          clipPath="url(#graph-clip)"
          style={{ transition: "none" }}
        />

        {/* Main Graph Line */}
        <path
          d={linePath}
          fill="none"
          stroke={lineColor}
          strokeWidth={6}
          strokeLinecap="round"
          strokeLinejoin="round"
          clipPath="url(#graph-clip)"
          filter="url(#glow)"
          style={{ transition: "none" }}
        />

        {/* Background Data Point Dots */}
        {absPoints.map((p, i) => {
          const dotScale = interpolate(
            currentX,
            [p.x, p.x + (maxX - minX) * 0.05],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <circle
              key={`dot-${i}`}
              cx={p.x}
              cy={p.y}
              r={6}
              fill={backgroundColor}
              stroke={lineColor}
              strokeWidth={3}
              style={{
                transform: `scale(${dotScale})`,
                transformOrigin: `${p.x}px ${p.y}px`,
                transition: "none",
              }}
            />
          );
        })}

        {/* Leading Dot Follower */}
        {chartProgress > 0 && (
          <circle
            cx={currentX}
            cy={currentY}
            r={10}
            fill={backgroundColor}
            stroke={lineColor}
            strokeWidth={4}
            filter="url(#glow)"
            style={{
              transform: `scale(${leadingDotScale})`,
              transformOrigin: `${currentX}px ${currentY}px`,
              transition: "none",
            }}
          />
        )}
      </svg>

      {/* Header UI */}
      <div
        style={{
          position: "absolute",
          top: height * 0.08,
          left: width * 0.1,
          right: width * 0.1,
          display: "flex",
          justifyContent: "space-between",
          alignItems: "flex-start",
        }}
      >
        <div style={{ display: "flex", flexDirection: "column" }}>
          <h1
            style={{
              margin: 0,
              fontSize: 48,
              fontWeight: 600,
              color: textColor,
              opacity: titleOpacity,
            }}
          >
            {title}
          </h1>
          <h2
            style={{
              margin: 0,
              fontSize: 32,
              fontWeight: 400,
              color: textColor,
              opacity: titleOpacity * 0.5,
              marginTop: 8,
            }}
          >
            {subtitle}
          </h2>
        </div>

        {/* Growth Text Badge */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            padding: "16px 32px",
            borderRadius: "100px",
            position: "relative",
            overflow: "hidden",
            opacity: interpolate(growthBadgeScale, [0, 1], [0, 1]),
            transform: `scale(${growthBadgeScale})`,
            transformOrigin: "center right",
          }}
        >
          {/* Badge Background */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              backgroundColor: lineColor,
              opacity: 0.15,
            }}
          />
          {/* Badge Border */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              border: `2px solid ${lineColor}`,
              opacity: 0.3,
              borderRadius: "100px",
            }}
          />
          <span
            style={{
              position: "relative",
              fontSize: 48,
              fontWeight: 700,
              color: lineColor,
            }}
          >
            {growthText}
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default GrowthChart;